css:
.migration-sim-container {
    padding: 28px;
    background: #f4f1ec;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.migration-sim-header {
    background: #1a2744;
    color: #f4f1ec;
    padding: 28px 32px;
    border-radius: 4px;
    margin-bottom: 20px;
    border-left: 6px solid #c4a64b;
    display: block;
}
.migration-sim-header-meta {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #c4a64b;
    margin-bottom: 10px;
    font-weight: 600;
}
.migration-sim-header h1 {
    font-size: 1.7rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    color: #ffffff;
    line-height: 1.2;
}
.migration-sim-subtitle {
    font-size: 0.95rem;
    color: #d6d2c8;
    font-style: italic;
    line-height: 1.4;
}
.migration-sim-period-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 16px;
    margin-bottom: 18px;
    padding: 12px 18px;
    background: #ffffff;
    border: 1px solid #d6d2c8;
    border-radius: 4px;
}
.migration-sim-round-pill {
    background: #1a2744;
    color: #ffffff;
    padding: 5px 16px;
    border-radius: 20px;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.04em;
}
.migration-sim-round-pill span {
    margin: 0 2px;
}
.migration-sim-round-name {
    font-weight: 600;
    color: #1a2744;
    font-size: 1rem;
}
.migration-sim-briefing {
    background: #ffffff;
    border: 1px solid #d6d2c8;
    border-left: 4px solid #1a2744;
    padding: 22px 26px;
    border-radius: 4px;
    margin-bottom: 24px;
}
.migration-sim-briefing h3 {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b6b6b;
    margin: 0 0 12px 0;
    font-weight: 700;
}
.migration-sim-briefing #briefingText {
    font-size: 0.95rem;
    line-height: 1.65;
    color: #2a2a2a;
}
.migration-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.migration-sim-kpi {
    background: #ffffff;
    border: 1px solid #d6d2c8;
    padding: 18px 18px;
    border-radius: 4px;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.migration-sim-kpi:hover {
    border-color: #c4a64b;
    transform: translateY(-2px);
}
.migration-sim-kpi-feature {
    border-top: 4px solid #c4a64b;
    background: #fffdf5;
}
.migration-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #6b6b6b;
    margin-bottom: 8px;
    font-weight: 600;
}
.migration-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 4px;
    line-height: 1.1;
}
.migration-sim-kpi-primary {
    color: #8a6d1f;
}
.migration-sim-kpi-hint {
    font-size: 0.7rem;
    color: #6e6e6e;
    line-height: 1.3;
}
.migration-sim-stakeholder-panel {
    background: #ffffff;
    border: 1px solid #d6d2c8;
    padding: 22px 26px;
    border-radius: 4px;
    margin-bottom: 24px;
}
.migration-sim-stakeholder-panel h3 {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b6b6b;
    margin: 0 0 18px 0;
    font-weight: 700;
}
.migration-sim-stake-row {
    display: grid;
    grid-template-columns: 220px 1fr 60px;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
}
.migration-sim-stake-label {
    font-size: 0.9rem;
    color: #1a2744;
    font-weight: 500;
}
.migration-sim-stake-bar {
    background: #ece8e0;
    height: 18px;
    border-radius: 2px;
    overflow: hidden;
}
.migration-sim-stake-fill {
    height: 100%;
    transition: width 0.5s ease;
}
.migration-sim-stake-fill-emp { background: linear-gradient(90deg, #1a4d80, #2d6ea8); }
.migration-sim-stake-fill-nat { background: linear-gradient(90deg, #b85c2c, #d97840); }
.migration-sim-stake-fill-mig { background: linear-gradient(90deg, #2d6a4f, #52b788); }
.migration-sim-stake-fill-fam { background: linear-gradient(90deg, #7a4b8a, #a16ab1); }
.migration-sim-stake-num {
    font-weight: 700;
    color: #1a2744;
    text-align: right;
    font-size: 0.95rem;
}
.migration-sim-controls {
    background: #ffffff;
    border: 1px solid #d6d2c8;
    padding: 26px 28px;
    border-radius: 4px;
    margin-bottom: 24px;
}
.migration-sim-controls h3 {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b6b6b;
    margin: 0 0 18px 0;
    font-weight: 700;
}
.migration-sim-control-group {
    margin-bottom: 22px;
    padding-bottom: 18px;
    border-bottom: 1px dashed #d6d2c8;
}
.migration-sim-control-group:last-of-type {
    border-bottom: none;
    margin-bottom: 12px;
}
.migration-sim-control-group h4 {
    font-size: 0.95rem;
    color: #1a2744;
    font-weight: 600;
    margin: 0 0 14px 0;
}
.migration-sim-weight-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 12px;
}
.migration-sim-controls label {
    display: flex;
    flex-direction: column;
    font-size: 0.8rem;
    color: #4a4a4a;
    font-weight: 500;
    margin-bottom: 12px;
}
.migration-sim-controls label span {
    margin-bottom: 6px;
}
.migration-sim-controls input[type="number"],
.migration-sim-controls select {
    background: #faf8f4;
    border: 1px solid #c4bfae;
    color: #1a2744;
    border-radius: 3px;
    padding: 9px 11px;
    font-size: 0.95rem;
    width: 100%;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.migration-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.migration-sim-controls input[type="number"]:focus,
.migration-sim-controls select:focus {
    outline: none;
    border-color: #c4a64b;
    box-shadow: 0 0 0 3px rgba(196,166,75,0.18);
}
.migration-sim-controls #nextPeriodBtn {
    background: #1a2744;
    color: #ffffff;
    border: none;
    padding: 12px 32px;
    border-radius: 3px;
    font-weight: 600;
    letter-spacing: 0.04em;
    margin-right: 10px;
    margin-top: 8px;
    transition: background 0.2s ease;
}
.migration-sim-controls #nextPeriodBtn:hover {
    background: #2c3d5e;
}
.migration-sim-controls #undoBtn {
    background: transparent;
    color: #6b6b6b;
    border: 1px solid #c4bfae;
    padding: 10px 20px;
    border-radius: 3px;
    font-size: 0.85rem;
    margin-top: 8px;
    transition: background 0.2s ease, color 0.2s ease;
}
.migration-sim-controls #undoBtn:hover {
    background: #faf8f4;
    color: #1a2744;
}
.migration-sim-history-section,
.migration-sim-chart-section {
    background: #ffffff;
    border: 1px solid #d6d2c8;
    padding: 22px 26px;
    border-radius: 4px;
    margin-bottom: 24px;
}
.migration-sim-history-section h3,
.migration-sim-chart-section h3 {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b6b6b;
    margin: 0 0 16px 0;
    font-weight: 700;
}
.migration-sim-history-section table {
    font-size: 0.88rem;
    color: #2a2a2a;
    width: 100%;
}
.migration-sim-history-section table th {
    background: #faf8f4;
    color: #1a2744;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.08em;
    border-bottom: 2px solid #c4a64b;
    padding: 10px 12px;
}
.migration-sim-history-section table td {
    padding: 9px 12px;
    border-bottom: 1px solid #ece8e0;
}
.migration-sim-chart-section canvas {
    max-height: 340px;
}

@media (max-width: 768px) {
    .migration-sim-container { padding: 14px; }
    .migration-sim-header { padding: 20px; }
    .migration-sim-header h1 { font-size: 1.3rem; }
    .migration-sim-stake-row {
        grid-template-columns: 1fr;
        gap: 6px;
    }
    .migration-sim-stake-num {
        text-align: left;
    }
    .migration-sim-weight-grid {
        grid-template-columns: 1fr;
    }
    .migration-sim-kpi-value {
        font-size: 1.4rem;
    }
}

/* --- EQIL 2026-08-07: focus, motion, completion panel --- */
.migration-sim-container :focus-visible,
.migration-sim-container select:focus-visible,
.migration-sim-container input:focus-visible,
.migration-sim-container button:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
    border-radius: 3px;
}
.migration-sim-actions { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.migration-sim-completion {
    background: #ffffff;
    border: 1px solid #d6d2c8;
    border-left: 6px solid #8a6d1f;
    border-radius: 4px;
    padding: 22px 26px;
    margin: 20px 0;
    color: #1a2744;
}
.migration-sim-debrief h3 { margin: 0 0 10px; font-size: 1.15rem; }
.migration-sim-debrief-headline { font-size: 1rem; margin-bottom: 14px; }
.migration-sim-debrief-list { list-style: none; padding: 0; margin: 0 0 14px; display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 8px; }
.migration-sim-debrief-list li { display: flex; justify-content: space-between; gap: 12px; background: #f4f1ec; border: 1px solid #e2ddd4; border-radius: 4px; padding: 8px 12px; }
.migration-sim-debrief-k { color: #5a5750; font-size: 0.82rem; }
.migration-sim-debrief-v { font-weight: 700; }
.migration-sim-debrief-insights p { margin: 0 0 8px; font-size: 0.9rem; line-height: 1.5; }
@media (prefers-reduced-motion: reduce) {
    .migration-sim-container *,
    .migration-sim-container *::before,
    .migration-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

