            const wE = elE ? (parseFloat(elE.value) || 0) : (decisions.wEmployers || 0);
            const wN = elN ? (parseFloat(elN.value) || 0) : (decisions.wNatives || 0);
            const wM = elM ? (parseFloat(elM.value) || 0) : (decisions.wMigrants || 0);
            const wF = elF ? (parseFloat(elF.value) || 0) : (decisions.wFamilies || 0);

            decisions.wEmployers = wE;
            decisions.wNatives = wN;
            decisions.wMigrants = wM;
            decisions.wFamilies = wF;

            const total = wE + wN + wM + wF;
            if (Math.abs(total - 100) > 0.5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('weight_warning') + ' (' + Math.round(total) + ')', 'warning'
                );
                return false;
            }

            const round = (window.mySimulation.state && window.mySimulation.state.currentPeriod) || 1;

            if (round >= 2) {
                const integrationInput = document.getElementById('integrationInput');
                if (integrationInput) {
                    decisions.integrationSpend = parseFloat(integrationInput.value);
                    if (isNaN(decisions.integrationSpend)) decisions.integrationSpend = 0;
                }
                if (decisions.integrationSpend < 0 || decisions.integrationSpend > 600) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('integration_warning'), 'warning'
                    );
                    return false;
                }
            }

            if (round >= 3) {
                const policyInput = document.getElementById('policyInput');
                if (policyInput) decisions.policyChoice = policyInput.value;
                const flowInput = document.getElementById('flowInput');
                if (flowInput) {
                    decisions.flowCap = parseInt(flowInput.value);
                    if (isNaN(decisions.flowCap)) decisions.flowCap = 25000;
                }
                if (!POLICIES[decisions.policyChoice]) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('policy_warning'), 'warning'
                    );
                    return false;
                }
                if (decisions.flowCap < 5000 || decisions.flowCap > 100000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('flow_warning'), 'warning'
                    );
                    return false;
                }
            }

            self._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const round = state.currentPeriod;

            const policy = round >= 3 ? (d.policyChoice || 'F') : 'F';
            const flowCap = round >= 3 ? (d.flowCap || 50000) : 50000;
            const integrationSpend = round >= 2 ? (d.integrationSpend || 0) : 0;

            const p = POLICIES[policy];
            const flowMult = flowCap / 50000;

            const aggGDP = 530 * flowMult * p.gdpMult;
            const nativeWagePct = p.wageEffect;
            const migrantWelfare = 600 * flowMult * p.migrantPremium;
            const remittances = 130 * flowMult;

            const housingCost = round >= 2 ? 380 * flowMult : 0;
            const fiscal5yr = round >= 2 ? -200 * flowMult * p.fiscalCost5yr - integrationSpend * 0.4 : 0;
            const fiscal30yr = round >= 2 ? 4200 * flowMult - integrationSpend * 6 : 0;
            const brainClosures = round >= 2 ? Math.round(23 * flowMult * p.brainDrainMult) : 0;
            const integrationDeficit = Math.max(0, p.integrationCostNeeded - integrationSpend);
            const integrationScore = round >= 2
                ? Math.max(0, Math.min(100, 60 - integrationDeficit * 0.1 + integrationSpend * 0.05))
                : 50;

            const wTotal = (d.wEmployers || 0) + (d.wNatives || 0) + (d.wMigrants || 0) + (d.wFamilies || 0);
            const wE = wTotal > 0 ? d.wEmployers / wTotal : 0.25;
            const wN = wTotal > 0 ? d.wNatives / wTotal : 0.25;
            const wM = wTotal > 0 ? d.wMigrants / wTotal : 0.25;
            const wF = wTotal > 0 ? d.wFamilies / wTotal : 0.25;

            const employerScore = Math.max(0, Math.min(100, aggGDP / 8));
            const nativeScore   = Math.max(0, Math.min(100, 100 + nativeWagePct * 14 - housingCost / 10));
            const migrantBase   = migrantWelfare / 9;
            const migrantScore  = Math.max(0, Math.min(100, migrantBase * (round >= 2 ? (integrationScore / 60) : 1)));
            const familyScore   = Math.max(0, Math.min(100, 30 + remittances / 3 - brainClosures * 1.2));

            const consensusScore = wE * employerScore + wN * nativeScore + wM * migrantScore + wF * familyScore;

            state.domainState.consensusHistory.push(Math.round(consensusScore));
            state.domainState.employerHistory.push(Math.round(employerScore));
            state.domainState.nativeHistory.push(Math.round(nativeScore));
            state.domainState.migrantHistory.push(Math.round(migrantScore));
            state.domainState.familyHistory.push(Math.round(familyScore));
            // platform score: this round consensus score, already 0 to 100, the same figure the final verdict reads from the last round
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(consensusScore))) });

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: round + 1 });
                self._updateBars({
                    employerScore: Math.round(employerScore),
                    nativeScore: Math.round(nativeScore),
                    migrantScore: Math.round(migrantScore),
                    familyScore: Math.round(familyScore)
                });
            }, 500);

            return {
                period: round,
                aggGDP: Math.round(aggGDP),
                nativeWagePct: Number(nativeWagePct.toFixed(1)),
                migrantWelfare: Math.round(migrantWelfare),
                remittances: Math.round(remittances),
                housingCost: Math.round(housingCost),
                fiscal5yr: Math.round(fiscal5yr),
                fiscal30yr: Math.round(fiscal30yr),
                brainClosures: brainClosures,
                integrationScore: Math.round(integrationScore),
                integrationSpend: integrationSpend,
                employerScore: Math.round(employerScore),
                nativeScore: Math.round(nativeScore),
                migrantScore: Math.round(migrantScore),
                familyScore: Math.round(familyScore),
                consensusScore: Math.round(consensusScore),
                policyName: p.name,
                policyCode: policy,
                flowCap: flowCap
            };
        }

