        getPerformanceSummary(history) {
            if (!history.length) return {};
            const last = history[history.length - 1].results || {};
            const consensus = last.consensusScore || 0;

            let performance = 'beginner';
            if (consensus >= 65) performance = 'excellent';
            else if (consensus >= 50) performance = 'good';
            const perfKey = 'perf_' + performance;
            // The consensus score is already a weighted 0-100 figure, so the composite is
            // the consensus itself. No change to how it is computed or banded.
            const overall = Math.max(0, Math.min(100, Math.round(consensus)));

            const stakes = [
                { key: 'w_employers', score: last.employerScore || 0 },
                { key: 'w_natives',   score: last.nativeScore   || 0 },
                { key: 'w_migrants',  score: last.migrantScore  || 0 },
                { key: 'w_families',  score: last.familyScore   || 0 }
            ];
            stakes.sort((a, b) => a.score - b.score);

            const insights = [];
            insights.push(this._t('insight_weakest') + ' ' + this._t(stakes[0].key) +
                          ' (' + stakes[0].score + '/100). ' + this._t('insight_weakest_tail'));
            if (last.policyName) {
                insights.push(this._t('insight_policy') + ' ' + this._policyName(last.policyCode, last.policyName) + ' — ' +
                              (last.flowCap || 0).toLocaleString() + ' ' + this._t('workers_per_year'));
            }
            if (last.brainClosures && last.brainClosures > 15) {
                insights.push(last.brainClosures + ' ' + this._t('insight_braindrain'));
            }
            if (last.fiscal5yr !== undefined && last.fiscal5yr < 0) {
                insights.push(this._t('insight_fiscal_a') + ' (CU ' + last.fiscal5yr + 'm). ' +
                              this._t('insight_fiscal_b'));
            }
            insights.push(this._t('insight_reflect'));

            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                consensus: consensus,
                employerScore: last.employerScore || 0,
                nativeScore: last.nativeScore || 0,
                migrantScore: last.migrantScore || 0,
                familyScore: last.familyScore || 0,
                performance: performance,
                performanceKey: perfKey,
                performanceLabel: this._t(perfKey),
                insights: insights
            };
        }

        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                const v = window.mySimulation.t(key);
                if (v) return v;
            }
            return key;
        }

        /* policy name in the current language; the stored results keep the English name as data */
        _policyName(code, fallback) {
            let c = String(code || '');
            if (!POLICIES[c]) {
                c = Object.keys(POLICIES).filter(function(k) { return POLICIES[k].name === fallback; })[0] || '';
            }
            if (!c) return fallback || '';
            const k = 'policy_name_' + c.toLowerCase();
            const v = this._t(k);
            return (v && v !== k) ? v : POLICIES[c].name;
        }

        _isRunComplete(period) {
            const st = (window.mySimulation && window.mySimulation.state) || {};
            const maxP = parseInt(st.maxPeriods, 10) || 3;
            const hist = Array.isArray(st.history) ? st.history : [];
            if (hist.length >= maxP) return true;
            return (period || 1) > maxP;
        }

        _syncControlsFromDecisions(state) {
            const dec = (state && state.decisions) || {};
            const map = {
                wEmployersInput: 'wEmployers', wNativesInput: 'wNatives',
                wMigrantsInput: 'wMigrants', wFamiliesInput: 'wFamilies',
                integrationInput: 'integrationSpend', flowInput: 'flowCap'
            };
            Object.keys(map).forEach(function(id) {
                const el = document.getElementById(id);
                const v = dec[map[id]];
                if (el && v !== undefined && v !== null) el.value = String(v);
            });
            const p = document.getElementById('policyInput');
            if (p && dec.policyChoice) p.value = dec.policyChoice;
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = this._t.bind(this);
            const esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            const rows = [
                [t('w_employers'), esc(s.employerScore) + '/100'],
                [t('w_natives'), esc(s.nativeScore) + '/100'],
                [t('w_migrants'), esc(s.migrantScore) + '/100'],
                [t('w_families'), esc(s.familyScore) + '/100']
            ].map(function(r) {
                return '<li><span class="migration-sim-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="migration-sim-debrief-v">' + esc(r[1]) + '</span></li>';
            }).join('');
            const ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            return '<div class="migration-sim-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="migration-sim-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="migration-sim-debrief-list">' + rows + '</ul>' +
                     '<div class="migration-sim-debrief-insights">' + ins + '</div>' +
                   '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const round = state.currentPeriod;
            const d = state.decisions || {};
            if (round === 1 && (d.wMigrants || 0) < 15 && results.migrantWelfare > 400) {
                return window.mySimulation.t('hint_migrant_weight');
            }
            if (round === 2 && results.brainClosures > 20) {
                return window.mySimulation.t('hint_brain_drain');
            }
            if (round === 3 && results.fiscal5yr < -300 && (results.integrationSpend || 0) < 150) {
                return window.mySimulation.t('hint_integration_underfunded');
            }
            if (results.consensusScore < 35) {
                return window.mySimulation.t('hint_low_consensus');
            }
            if (round === 3 && results.policyCode === 'A') {
                return window.mySimulation.t('hint_open_borders');
            }
            if (round === 3 && results.policyCode === 'G') {
                return window.mySimulation.t('hint_rotating');
            }
            return null;
        }

