        _updateBriefing(state) {
            const _period = (state && state.currentPeriod) || 1;
            const _over = this._isRunComplete(_period);
            const _actions = document.querySelector('.migration-sim-actions');
            if (_actions) _actions.style.display = _over ? 'none' : 'flex';
            const _done = document.getElementById('completionPanel');
            if (_done) {
                _done.style.display = _over ? 'block' : 'none';
                if (_over && !_done.innerHTML) {
                    _done.innerHTML = (window.mySimulation && window.mySimulation.lastCompletionHTML) ||
                        ('<div class="migration-sim-debrief"><h3>' + this._t('debrief_heading') + '</h3></div>');
                }
            }
            if (_over) {
                ['round2Controls', 'round3Controls'].forEach(function(id) {
                    const el = document.getElementById(id);
                    if (el) el.style.display = 'none';
                });
                const wg = document.querySelector('.migration-sim-weight-grid');
                if (wg && wg.parentNode) wg.parentNode.style.display = 'none';
                return;
            }
            const round = Math.min((state.currentPeriod || 1), 3);
            const t = (k) => (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;

            const briefEl = document.getElementById('briefingText');
            const nameEl = document.getElementById('roundName');
            const r2 = document.getElementById('round2Controls');
            const r3 = document.getElementById('round3Controls');

            if (briefEl) {
                if (round === 1) briefEl.innerHTML = t('round1_brief');
                else if (round === 2) briefEl.innerHTML = t('round2_brief');
                else briefEl.innerHTML = t('round3_brief');
            }
            if (nameEl) {
                if (round === 1) nameEl.textContent = t('round_name_1');
                else if (round === 2) nameEl.textContent = t('round_name_2');
                else nameEl.textContent = t('round_name_3');
            }
            if (r2) r2.style.display = round >= 2 ? 'block' : 'none';
            if (r3) r3.style.display = round >= 3 ? 'block' : 'none';
        }

        _updateBars(scores) {
            const set = (id, v) => {
                const el = document.getElementById(id);
                if (el) el.style.width = Math.max(0, Math.min(100, v || 0)) + '%';
            };
            set('employerBar', scores.employerScore);
            set('nativeBar',   scores.nativeScore);
            set('migrantBar',  scores.migrantScore);
            set('familyBar',   scores.familyScore);
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new MigrationAdapter(), {
            simulationType: 'migration_tradeoff',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

})();
